          "text": "def transform(grid):\n    h,w=len(grid),len(grid[0])\n    from collections import Counter\n    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]\n    hdiv=[r for r,row in enumerate(grid) if len(set(row))==1 and row[0]!=bg]\n    vdiv=[c for c in range(w) if len({grid[r][c] for r in range(h)})==1 and grid[0][c]!=bg]\n    if not hdiv: return [row[:] for row in grid]\n    hc=grid[hdiv[0]][0]\n    hs=[r for r in hdiv if grid[r][0]==hc]\n    vs=[c for c in range(w) if all(grid[r][c]==hc for r in range(h) if r not in hs)]\n    if not vs: return [row[:] for row in grid]\n    rb=[-1]+hs+[h]; cb=[-1]+vs+[w]\n    bands=[(rb[i]+1,rb[i+1]) for i in range(len(rb)-1)]\n    panels=[(cb[i]+1,cb[i+1]) for i in range(len(cb)-1)]\n    src=max(((ri,ci) for ri in range(len(bands)) for ci in range(len(panels))),\n            key=lambda z:sum(v!=bg and v not in (hc,hc) for row in grid[bands[z[0]][0]:bands[z[0]][1]] for v in row[panels[z[1]][0]:panels[z[1]][1]]))\n    (ra,rz),(ca,cz)=bands[src[0]],panels[src[1]]\n    motif=[row[ca:cz] for row in grid[ra:rz]]\n    out=[row[:] for row in grid]\n    for a,b in bands:\n        for x,y in panels:\n            if (a,b)==bands[src[0]] and (x,y)==panels[src[1]]: continue\n            for r in range(a,b):\n                for c in range(x,y): out[r][c]=motif[(r-a)%len(motif)][(c-x)%len(motif[0])]\n    return out"
        }
