def transform(grid):
    # Mirror isolated non-background marks across the horizontal and vertical
    # symmetry axes defined by the full-width divider row and full-height divider column.
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Divider colors are uniform row/column colors distinct from the background.
    div_rows = [r for r,row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    div_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != bg]
    out = [row[:] for row in grid]
    if not div_rows and not div_cols:
        return out
    # Each marker is reflected across all present separator axes, preserving its color.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or r in div_rows or c in div_cols:
                continue
            rs = {r}
            cs = {c}
            for d in div_rows:
                rs.add(2*d-r)
            for d in div_cols:
                cs.add(2*d-c)
            for rr in rs:
                for cc in cs:
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = v
    return out
