def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda x: sum(v == x for row in grid for v in row))
    sep_rows = [r for r,row in enumerate(grid) if len(set(row)) == 1 and row[0] != bg]
    if not sep_rows:
        return [row[:] for row in grid]
    divider = grid[sep_rows[0]][0]
    out = [row[:] for row in grid]
    # Mirror all non-background cells across each solid divider axis.
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] == divider]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg or v == divider:
                continue
            rs = {r}
            cs = {c}
            for d in sep_rows:
                rs.add(2*d-r)
            for d in sep_cols:
                cs.add(2*d-c)
            for rr in rs:
                for cc in cs:
                    if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = v
    return out
PY
